fn op_env_var_register(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;
    for _ in 0..iters {
        unsafe {
            let lil = lil_new();
            if lil.is_null() {
                digest = fold(digest, 0xDEAD);
                continue;
            }

            let split_pos = data.iter().position(|&b| b == 0).unwrap_or(data.len().min(32)).min(32);
            let name_data = &data[..split_pos];
            let val_start = if split_pos < data.len() { split_pos + 1 } else { data.len() };
            let val_data = &data[val_start..];

            let mut name_buf: Vec<u8> = if name_data.is_empty() {
                b"x".to_vec()
            } else {
                name_data.iter().filter(|&&b| b != 0).copied().collect()
            };
            if name_buf.is_empty() {
                name_buf = b"x".to_vec();
            }
            name_buf.push(0);

            let mut val_buf: Vec<u8> = val_data.to_vec();
            val_buf.push(0);

            lil_push_env(lil);

            let val_v = lil_alloc_string(val_buf.as_ptr() as *const ::core::ffi::c_char);
            lil_set_var(lil, name_buf.as_ptr() as *const ::core::ffi::c_char, val_v, 1);
            lil_free_value(val_v);

            let got = lil_get_var(lil, name_buf.as_ptr() as *const ::core::ffi::c_char);
            let mut h = fold_value(0u64, got);

            let def_val = lil_alloc_string(b"default\0".as_ptr() as *const ::core::ffi::c_char);
            let got_or = lil_get_var_or(
                lil,
                b"nonexistent_var\0".as_ptr() as *const ::core::ffi::c_char,
                def_val,
            );
            h = fold_value(h, got_or);
            lil_free_value(def_val);

            let gval = lil_alloc_string(b"globalval\0".as_ptr() as *const ::core::ffi::c_char);
            lil_set_var(lil, b"gvar\0".as_ptr() as *const ::core::ffi::c_char, gval, 0);
            lil_free_value(gval);

            lil_register(lil, b"dummycmd\0".as_ptr() as *const ::core::ffi::c_char, Some(dummy_cmd));

            let call_result = lil_call(lil, b"dummycmd\0".as_ptr() as *const ::core::ffi::c_char, 0, ptr::null_mut());
            if !call_result.is_null() {
                h = fold_value(h, call_result);
                lil_free_value(call_result);
            }

            let arg1 = lil_alloc_string(b"arg1val\0".as_ptr() as *const ::core::ffi::c_char);
            let arg2 = lil_alloc_string(b"arg2val\0".as_ptr() as *const ::core::ffi::c_char);
            let mut args = [arg1, arg2];
            let call_result2 = lil_call(lil, b"dummycmd\0".as_ptr() as *const ::core::ffi::c_char, 2, args.as_mut_ptr());
            if !call_result2.is_null() {
                h = fold_value(h, call_result2);
                lil_free_value(call_result2);
            }
            lil_free_value(arg1);
            lil_free_value(arg2);

            let uname = lil_unused_name(lil, b"__tmp\0".as_ptr() as *const ::core::ffi::c_char);
            if !uname.is_null() {
                h = fold_value(h, uname);
                lil_free_value(uname);
            }

            let mut user_data: u64 = 0x12345678;
            lil_set_data(lil, &mut user_data as *mut u64 as *mut ::core::ffi::c_void);
            let got_data = lil_get_data(lil);
            if !got_data.is_null() {
                let dval = *(got_data as *const u64);
                h = fold(h, dval);
            }
            lil_set_data(lil, ptr::null_mut());

            lil_set_error(lil, b"test error\0".as_ptr() as *const ::core::ffi::c_char);
            let (h2, ef) = fold_error(h, lil);
            h = h2;
            last_err = ef;

            lil_set_error_at(lil, 42, b"positional error\0".as_ptr() as *const ::core::ffi::c_char);
            let (h2, ef) = fold_error(h, lil);
            h = h2;
            last_err = ef;

            lil_write(lil, b"hello from harness\0".as_ptr() as *const ::core::ffi::c_char);

            let env = lil_alloc_env(ptr::null_mut());
            if !env.is_null() {
                lil_free_env(env);
            }

            lil_pop_env(lil);
            lil_free(lil);

            digest = fold(digest, h);
        }
    }
    format!("op=env_var_register err={} digest={:016x}", last_err, digest)
}

fn op_expr_eval(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;
    for _ in 0..iters {
        unsafe {
            let lil = lil_new();
            if lil.is_null() {
                digest = fold(digest, 0xDEAD);
                continue;
            }

            let mut code_buf: Vec<u8> = data.to_vec();
            code_buf.push(0);

            let expr_val = lil_alloc_string(code_buf.as_ptr() as *const ::core::ffi::c_char);
            let result = lil_eval_expr(lil, expr_val);

            let mut h = fold_value(0u64, result);
            if !result.is_null() {
                let r_dbl = lil_to_double(result);
                h = fold(h, r_dbl.to_bits());
                lil_free_value(result);
            }

            let pv_result = lil_parse_value(lil, expr_val, 0);
            h = fold_value(h, pv_result);
            if !pv_result.is_null() {
                lil_free_value(pv_result);
            }

            let (h2, ef) = fold_error(h, lil);
            h = h2;
            last_err = ef;

            lil_free_value(expr_val);
            lil_free(lil);

            digest = fold(digest, h);
        }
    }
    format!("op=expr_eval err={} digest={:016x}", last_err, digest)
}

fn op_comprehensive_parse(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    let scripts: &[&[u8]] = &[
        b"set a 10; set b 20; expr $a + $b",
        b"if {expr 1} {set r yes} {set r no}; result $r",
        b"if {expr 0} {set r yes} {set r no}; result $r",
        b"func myfn {x y} {return [expr $x + $y]}; myfn 3 4",
        b"count {a b c d e}",
        b"list a b c d",
        b"set x hello; subst {$x world}",
        b"quote {hello world}",
        b"char 65",
        b"charat hello 1",
        b"codeat hello 0",
        b"substr hello 1 3",
        b"strpos hello ll",
        b"length hello",
        b"trim {  hello  }",
        b"strcmp abc def",
        b"strcmp abc abc",
        b"streq abc abc",
        b"expr 10 % 3",
        b"expr 0xff & 0x0f",
        b"expr 1 << 4",
        b"expr 5 == 5",
        b"expr 1 && 1",
        b"expr 1 || 0",
        b"set a [expr 2 + 3]; set b [expr $a * 2]; result $b",
        b"",
        b"#comment line\nset x 1",
        b"set x {braced string with spaces}; result $x",
    ];

    for _ in 0..iters {
        unsafe {
            let lil = lil_new();
            if lil.is_null() {
                digest = fold(digest, 0xDEAD);
                continue;
            }

            let mut h = 0u64;

            for script in scripts {
                h = run_script_fold(lil, script, h);
                let mut _msg: *const ::core::ffi::c_char = ptr::null();
                let mut _pos: usize = 0;
                let _ = lil_error(lil, &mut _msg, &mut _pos);
            }

            if !data.is_empty() {
                let parse_len = data.len().min(4096);
                let mut code_buf: Vec<u8> = data[..parse_len].to_vec();
                code_buf.push(0);
                let result = lil_parse(
                    lil,
                    code_buf.as_ptr() as *const ::core::ffi::c_char,
                    parse_len,
                    0,
                );
                h = fold_value(h, result);
                if !result.is_null() {
                    lil_free_value(result);
                }
            }

            h = fold_bytes(h, data);

            let (h2, ef) = fold_error(h, lil);
            h = h2;
            last_err = ef;

            lil_free(lil);
            digest = fold(digest, h);
        }
    }
    format!("op=comprehensive_parse err={} digest={:016x}", last_err, digest)
}

const LIL_CALLBACK_EXIT: i32 = 0;
const LIL_CALLBACK_WRITE: i32 = 1;

static mut WRITE_BUF: Vec<u8> = Vec::new();

unsafe extern "C" fn write_callback(
    _lil: lil_t,
    msg: *const ::core::ffi::c_char,
) {
    if !msg.is_null() {
        let bytes = cstr_bytes(msg);
        WRITE_BUF.extend_from_slice(bytes);
    }
}

unsafe extern "C" fn exit_callback(
    _lil: lil_t,
    _val: lil_value_t,
) {
}

fn op_callback_embedded(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;
    for _ in 0..iters {
        unsafe {
            let lil = lil_new();
            if lil.is_null() {
                digest = fold(digest, 0xDEAD);
                continue;
            }

            WRITE_BUF.clear();

            let write_cb: Option<unsafe extern "C" fn()> = Some(
                core::mem::transmute::<
                    unsafe extern "C" fn(lil_t, *const ::core::ffi::c_char),
                    unsafe extern "C" fn(),
                >(write_callback)
            );
            lil_callback(lil, LIL_CALLBACK_WRITE, write_cb);

            let exit_cb: Option<unsafe extern "C" fn()> = Some(
                core::mem::transmute::<
                    unsafe extern "C" fn(lil_t, lil_value_t),
                    unsafe extern "C" fn(),
                >(exit_callback)
            );
            lil_callback(lil, LIL_CALLBACK_EXIT, exit_cb);

            lil_write(lil, b"callback test\0".as_ptr() as *const ::core::ffi::c_char);

            let mut h = fold_bytes(0u64, &WRITE_BUF);

            let mut template: Vec<u8> = b"Hello <% set x 42; write $x %> World".to_vec();
            if !data.is_empty() {
                template.extend_from_slice(b" <% set y ");
                let num = {
                    let mut buf = [0u8; 4];
                    for (i, &b) in data.iter().enumerate().take(4) {
                        buf[i] = b;
                    }
                    u32::from_le_bytes(buf)
                };
                template.extend_from_slice(format!("{}", num).as_bytes());
                template.extend_from_slice(b"; write $y %>");
            }
            template.push(0);

            WRITE_BUF.clear();
            let embedded_result = lil_embedded(
                lil,
                template.as_ptr() as *const ::core::ffi::c_char,
                0,
            );
            if !embedded_result.is_null() {
                let eb = cstr_bytes(embedded_result);
                h = fold_bytes(h, eb);
                lil_freemem(embedded_result as *mut ::core::ffi::c_void);
            }

            h = fold_bytes(h, &WRITE_BUF);

            let script = b"write {hello from script}\0";
            let result = lil_parse(lil, script.as_ptr() as *const ::core::ffi::c_char, script.len() - 1, 0);
            if !result.is_null() {
                h = fold_value(h, result);
                lil_free_value(result);
            }
            h = fold_bytes(h, &WRITE_BUF);

            let (h2, ef) = fold_error(h, lil);
            h = h2;
            last_err = ef;

            lil_free(lil);
            digest = fold(digest, h);
        }
    }
    format!("op=callback_embedded err={} digest={:016x}", last_err, digest)
}

fn op_arg_freemem(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    for _ in 0..iters {
        unsafe {
            let mut h = 0u64;

            let v1 = lil_alloc_string(b"first\0".as_ptr() as *const ::core::ffi::c_char);
            let v2 = lil_alloc_string(b"second\0".as_ptr() as *const ::core::ffi::c_char);
            let v3 = lil_alloc_string(b"third\0".as_ptr() as *const ::core::ffi::c_char);
            let mut argv = [v1, v2, v3];

            let a0 = lil_arg(argv.as_mut_ptr(), 0);
            h = fold_value(h, a0);
            let a1 = lil_arg(argv.as_mut_ptr(), 1);
            h = fold_value(h, a1);
            let a2 = lil_arg(argv.as_mut_ptr(), 2);
            h = fold_value(h, a2);

            lil_free_value(v1);
            lil_free_value(v2);
            lil_free_value(v3);

            let lil = lil_new();
            if !lil.is_null() {
                let mut tmpl = b"Value: <% write ".to_vec();
                if !data.is_empty() {
                    let val = data[0] as u32;
                    tmpl.extend_from_slice(format!("{}", val).as_bytes());
                } else {
                    tmpl.extend_from_slice(b"0");
                }
                tmpl.extend_from_slice(b" %>");
                tmpl.push(0);

                let emb = lil_embedded(
                    lil,
                    tmpl.as_ptr() as *const ::core::ffi::c_char,
                    0,
                );
                if !emb.is_null() {
                    let eb = cstr_bytes(emb);
                    h = fold_bytes(h, eb);
                    lil_freemem(emb as *mut ::core::ffi::c_void);
                }

                if data.len() > 1 {
                    let end = data.len().min(64);
                    let mut tmpl2 = b"Pre <% ".to_vec();
                    for &b in &data[1..end] {
                        if b == b'%' || b == b'>' || b == b'<' || b == 0 {
                            tmpl2.push(b' ');
                        } else {
                            tmpl2.push(b);
                        }
                    }
                    tmpl2.extend_from_slice(b" %> Post");
                    tmpl2.push(0);

                    let emb2 = lil_embedded(
                        lil,
                        tmpl2.as_ptr() as *const ::core::ffi::c_char,
                        0,
                    );
                    if !emb2.is_null() {
                        let eb2 = cstr_bytes(emb2);
                        h = fold_bytes(h, eb2);
                        lil_freemem(emb2 as *mut ::core::ffi::c_void);
                    }
                }

                lil_free(lil);
            }

            h = fold_bytes(h, data);

            digest = fold(digest, h);
        }
    }
    format!("op=arg_freemem digest={:016x}", digest)
}

/// This operation exercises the built-in LIL commands.
/// Scripts are kept simple and non-looping to avoid timeouts.
fn op_builtin_cmds(data: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0i32;

    // Simple, fast scripts that exercise built-in commands without loops
    let scripts: &[&[u8]] = &[
        // fnc_set, fnc_result
        b"set abc 123; set abc",
        // fnc_expr - arithmetic
        b"expr 2 + 3 * 4",
        b"expr (2 + 3) * 4",
        b"expr 10 / 3",
        b"expr 10 % 3",
        b"expr 1 << 4",
        b"expr 256 >> 4",
        b"expr 0xff & 0x0f",
        b"expr 0xf0 | 0x0f",
        b"expr 5 == 5",
        b"expr 5 != 3",
        b"expr 5 > 3",
        b"expr 3 < 5",
        b"expr 1 && 1",
        b"expr 1 || 0",
        b"expr !0",
        b"expr ~0",
        b"expr -5",
        // fnc_list
        b"list 1 2 3 4 5",
        // fnc_count
        b"count {a b c d e f}",
        // fnc_index
        b"index {a b c d e} 2",
        b"index {hello world foo} 0",
        // fnc_indexof
        b"indexof {apple banana cherry} banana",
        b"indexof {a b c d} x",
        // fnc_append
        b"set mylist {a b c}; append mylist d e f; set mylist",
        // fnc_concat
        b"concat {a b} {c d} {e f}",
        // fnc_quote
        b"quote {this is [a] $test}",
        // fnc_char
        b"char 65",
        b"char 97",
        // fnc_charat
        b"charat hello 0",
        b"charat hello 4",
        // fnc_codeat
        b"codeat hello 0",
        // fnc_substr
        b"substr hello 1 3",
        b"substr abcdef 2 4",
        // fnc_strpos
        b"strpos {hello world} world",
        b"strpos {abcdef} cd",
        // fnc_length
        b"length {hello world}",
        // fnc_trim
        b"trim {  hello  }",
        // fnc_strcmp
        b"strcmp abc abc",
        b"strcmp abc def",
        b"strcmp def abc",
        // fnc_streq
        b"streq hello hello",
        b"streq hello world",
        // fnc_subst
        b"set name world; subst {hello $name}",
        // fnc_eval
        b"eval {expr 2 + 3}",
        b"eval {set q 42; expr $q * 2}",
        // fnc_if
        b"if {expr 1 == 1} {set r true} {set r false}; set r",
        b"if {expr 1 == 0} {set r true} {set r false}; set r",
        // fnc_func, fnc_return
        b"func myfn {x y} {return [expr $x + $y]}; myfn 3 4",
        b"func rettest {} { return 42 }; rettest",
        b"func restest {} { result 99 }; restest",
        // fnc_inc, fnc_dec
        b"set x 5; inc x; set x",
        b"set x 10; dec x; set x",
        b"set x 5; inc x 10; set x",
        b"set x 10; dec x 3; set x",
        // fnc_local
        b"func testlocal {} { local mylocal; set mylocal 42; set mylocal }; testlocal",
        // fnc_write
        b"write {hello world}",
        // fnc_catch / fnc_error
        b"catch {expr 1 + 2}",
        b"catch {error {fail}}",
        // fnc_lmap
        b"lmap {a b c} {x y z}; list $x $y $z",
        // fnc_rename
        b"func oldfn {} { return old }; rename oldfn newfn; newfn",
        // fnc_unusedname
        b"unusedname test",
        // fnc_reflect
        b"reflect version",
        b"reflect func-count",
        // fnc_jaileval
        b"jaileval {expr 10 + 20}",
        // fnc_topeval
        b"func t1 {} { topeval {set topvar 42} }; t1; set topvar",
        // fnc_filter (small list, no loop risk)
        b"filter x {1 2 3 4 5} {expr $x > 3}",
        // fnc_foreach (small, bounded)
        b"set result {}; foreach item {alpha beta} {append result $item}; set result",
        // fnc_for (small, bounded - 3 iterations)
        b"set s 0; for {set i 0} {expr $i < 3} {inc i} {set s [expr $s + $i]}; set s",
        // fnc_while (small, bounded - 3 iterations)
        b"set i 0; set s 0; while {expr $i < 3} {set s [expr $s + $i]; inc i}; set s",
        // Multiple function calls
        b"func add {a b} { return [expr $a + $b] }; func mul {a b} { return [expr $a * $b] }; mul [add 2 3] [add 4 5]",
        // Empty function
        b"func empty {} {}; empty",
        // Complex expression with variables
        b"set a 10; set b 20; set c [expr $a * $b + ($a - $b)]; set c",
        // Nested braces
        b"set x {{nested {braces}}}; set x",
        // Comment
        b"#comment line\nset x 1",
        // fnc_catcher
        b"catcher {return caught}",
        // fnc_downeval
        b"func outer {} { func inner {} { downeval {set z 999} }; inner; set z }; outer",
        // fnc_upeval
        b"func outer2 {} { func inner2 {} { upeval {set uv 77} }; inner2; set uv }; outer2",
        // fnc_enveval
        b"func testenv {} { set a 100; enveval {set b [expr $a + 1]} }; testenv",
        // reflect more
        b"reflect funcs",
        b"reflect globals",
        b"set rv 42; reflect has-global rv",
        b"reflect has-global nonexistent",
        // slice
        b"set l {a b c d e f}; slice $l 1 3",
        // exit (with callback set)
        b"set before 1; catch {exit 0}; set before",
        // func deletion
        b"func todel {} { return 1 }; todel; rename todel {}",
        // foreach with pairs
        b"set result {}; foreach {k v} {a 1 b 2} {append result $k $v}; set result",
        // Dollar substitution
        b"set x 42; set y {$x}; subst $y",
    ];

    for _ in 0..iters {
        unsafe {
            let lil = lil_new();
            if lil.is_null() {
                digest = fold(digest, 0xDEAD);
                continue;
            }

            // Set up callbacks so exit/write commands don't crash
            let exit_cb: Option<unsafe extern "C" fn()> = Some(
                core::mem::transmute::<
                    unsafe extern "C" fn(lil_t, lil_value_t),
                    unsafe extern "C" fn(),
                >(exit_callback)
            );
            lil_callback(lil, LIL_CALLBACK_EXIT, exit_cb);

            let write_cb: Option<unsafe extern "C" fn()> = Some(
                core::mem::transmute::<
                    unsafe extern "C" fn(lil_t, *const ::core::ffi::c_char),
                    unsafe extern "C" fn(),
                >(write_callback)
            );
            lil_callback(lil, LIL_CALLBACK_WRITE, write_cb);

            WRITE_BUF.clear();

            let mut h = 0u64;

            for script in scripts {
                h = run_script_fold(lil, script, h);
                // Clear any error state between scripts
                let mut _msg: *const ::core::ffi::c_char = ptr::null();
                let mut _pos: usize = 0;
                let ef = lil_error(lil, &mut _msg, &mut _pos);
                h = fold(h, ef as u64);
            }

            // Make digest input-sensitive by folding data bytes
            // Don't parse arbitrary user data to avoid potential infinite loops
            h = fold_bytes(h, data);

            // Also use data to set a variable and read it back
            if !data.is_empty() {
                let val_len = data.len().min(64);
                let mut val_buf: Vec<u8> = Vec::with_capacity(val_len + 1);
                for &b in &data[..val_len] {
                    // Only use printable ASCII to avoid issues
                    let c = (b % 95) + 32; // map to printable range
                    val_buf.push(c);
                }
                val_buf.push(0);
                let val_v = lil_alloc_string(val_buf.as_ptr() as *const ::core::ffi::c_char);
                lil_set_var(lil, b"_input_var\0".as_ptr() as *const ::core::ffi::c_char, val_v, 1);
                lil_free_value(val_v);

                let got = lil_get_var(lil, b"_input_var\0".as_ptr() as *const ::core::ffi::c_char);
                h = fold_value(h, got);
            }

            h = fold_bytes(h, &WRITE_BUF);

            let (h2, ef) = fold_error(h, lil);
            h = h2;
            last_err = ef;

            lil_free(lil);
            digest = fold(digest, h);
        }
    }
    format!("op=builtin_cmds err={} digest={:016x}", last_err, digest)
}

pub fn ops() -> Vec<(&'static str, fn(&[u8], u64) -> String)> {
    vec![
        ("parse_eval", op_parse_eval as fn(&[u8], u64) -> String),
        ("value_ops", op_value_ops as fn(&[u8], u64) -> String),
